from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from pathlib import Path
import os, tempfile

pptx = Path('/home/user/Desktop/21_0.pptx')
ns = {
    'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
    'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
}

def update_title(xml_bytes, title_id):
    root = etree.fromstring(xml_bytes)
    matches = root.xpath(f'//*[@id=\"{title_id}\"]')
    if not matches:
        raise RuntimeError(f'title id {title_id} not found')
    shape = matches[0]
    while shape is not None and shape.tag "'!= '"'{%s}sp' % ns['p']:
        shape = shape.getparent()
    if shape is None:
        raise RuntimeError(f'title shape {title_id} not found')
    for rpr in shape.xpath('.//a:rPr | .//a:endParaRPr', namespaces=ns):
        rpr.set('b', '1')
        solid = rpr.find('{%s}solidFill' % ns['a'])
        if solid is None:
            solid = etree.Element('{%s}solidFill' % ns['a'])
            rpr.insert(0, solid)
        for child in list(solid):
            solid.remove(child)
        srgb = etree.SubElement(solid, '{%s}srgbClr' % ns['a'])
        srgb.set('val', '000000')
    return etree.tostring(root, xml_declaration=True, encoding='UTF-8', standalone=True)

def remove_shapes(xml_bytes, ids):
    root = etree.fromstring(xml_bytes)
    removed = []
    for sid in ids:
        matches = root.xpath(f'//*[@id=\"{sid}\"]')
        if not matches:
            continue
        node = matches[0]
        shape = node
        while shape is not None and shape.getparent() is not None and shape.getparent().tag "'!= '"'{%s}spTree' % ns['p']:
            shape = shape.getparent()
        if shape is not None and shape.getparent() is not None:
            shape.getparent().remove(shape)
            removed.append(sid)
    missing = set(ids) - set(removed)
    if missing:
        raise RuntimeError(f'missing/removal failed for ids: {sorted(missing)}')
    return etree.tostring(root, xml_declaration=True, encoding='UTF-8', standalone=True)

with ZipFile(pptx, 'r') as zin:
    entries = {info.filename: zin.read(info.filename) for info in zin.infolist()}
    infos = zin.infolist()

entries['ppt/slides/slide2.xml'] = update_title(entries['ppt/slides/slide2.xml'], '56')
entries['ppt/slides/slide3.xml'] = update_title(entries['ppt/slides/slide3.xml'], '77')
entries['ppt/slides/slide4.xml'] = remove_shapes(entries['ppt/slides/slide4.xml'], {'79','80','81','82','83','84','89','90','91','92'})

fd, tmpname = tempfile.mkstemp(prefix='21_0.', suffix='.pptx', dir=str(pptx.parent))
os.close(fd)
try:
    with ZipFile(tmpname, 'w', ZIP_DEFLATED) as zout:
        for info in infos:
            data = entries[info.filename]
            zi = info
            # Keep original metadata where practical; ZipFile.writestr accepts ZipInfo.
            zout.writestr(zi, data)
    os.replace(tmpname, pptx)
finally:
    if os.path.exists(tmpname):
        os.unlink(tmpname)
print('patched', pptx)
